"use strict";
exports.makeAudio = function makeAudio(n) {
  const u = new Uint8Array(n);
  for (let i = 0; i < n; i++) u[i] = (i * 7 + 3) % 256;
  return { uint8Array: u, label: "aud-" + n };
};
